        c.presetIndex = TypeConversions.int32ToUint16(presetIndex)
        c.bank = TypeConversions.int32ToUint16(bank)
        return true
    }

    public func channelSetPan(_ channel: Double, _ pan: Double) throws {
        for v in self._voices {
            if v.playingChannel == channel && v.playingPreset != -1.0 {
                let newPan: Double = try jsNonNull(v.region).pan + pan - 0.5
                if newPan <= -0.5 {
                    v.panFactorLeft = 1.0
                    v.panFactorRight = 0.0
                } else if newPan >= 0.5 {
                    v.panFactorLeft = 0.0
                    v.panFactorRight = 1.0
                } else {
                    v.panFactorLeft = Math.sqrt(0.5 - newPan)
                    v.panFactorRight = Math.sqrt(0.5 + newPan)
                }
            }
        }
        self._channelInit(channel).panOffset = pan - 0.5
    }

    public func channelSetVolume(_ channel: Double, _ volume: Double) {
        let c: Channel = self._channelInit(channel)
        let gainDb: Double = SynthHelper.gainToDecibels(volume)
        let gainDBChange: Double = gainDb - c.gainDb
        if gainDBChange == 0.0 {
            return
        }
        for v in self._voices {
            if v.playingChannel == channel && v.playingPreset != -1.0 {
                v.noteGainDb += gainDBChange
            }
        }
        c.gainDb = gainDb
    }

    public func channelSetPitchWheel(_ channel: Double, _ pitchWheel: Double) throws {
        let c: Channel = self._channelInit(channel)
        if c.pitchWheel == pitchWheel {
            return
        }
        c.pitchWheel = TypeConversions.int32ToUint16(pitchWheel)
        try self._channelApplyPitch(channel, c)
    }

    public func channelSetPerNotePitchWheel(_ channel: Double, _ key: Double, _ pitchWheel: Double) throws {
        var paramkey = try key
        if self._transpositionPitches.has(channel) {
            try paramkey += jsNonNull(self._transpositionPitches.get(channel))
        }
        if self._liveTranspositionPitches.has(channel) {
            try paramkey += jsNonNull(self._liveTranspositionPitches.get(channel))
        }
        let c: Channel = self._channelInit(channel)
        if c.perNotePitchWheel.has(paramkey) && c.perNotePitchWheel.get(paramkey) == pitchWheel {
            return
        }
        c.perNotePitchWheel.set(paramkey, pitchWheel)
        try self._channelApplyPitch(channel, c, paramkey)
    }

    private func _channelApplyPitch(_ channel: Double, _ c: Channel, _ key: Double = -1.0) throws {
        for v in self._voices {
            if v.playingChannel == channel && v.playingPreset != -1.0 && (key == -1.0 || v.playingKey == key) {
                try v.updatePitchRatio(c, self.outSampleRate)
            }
        }
    }

    public func channelSetPitchRange(_ channel: Double, _ pitchRange: Double) throws {
        let c: Channel = self._channelInit(channel)
        if c.pitchRange == pitchRange {
            return
        }
        c.pitchRange = pitchRange
        if c.pitchWheel != 8192.0 {
            try self._channelApplyPitch(channel, c)
        }
    }

    public func channelSetTuning(_ channel: Double, _ tuning: Double) throws {
        let c: Channel = self._channelInit(channel)
        if c.tuning == tuning {
            return
        }
        c.tuning = tuning
        try self._channelApplyPitch(channel, c)
    }

    /**
     * Apply a MIDI control change to the channel (not all controllers are supported!)
     */
    public func channelMidiControl(_ channel: Double, _ controller: ControllerType, _ controlValue: Double) throws {
        let c: Channel = self._channelInit(channel)
        switch controller {
        case ControllerType.DataEntryFine:
            c.midiData = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiData, 16256), controlValue))
            if c.midiRpn == 0.0 {
                try self.channelSetPitchRange(channel, (jsShr(c.midiData, 7)) + 0.01 * (jsAnd(c.midiData, 127)))
            } else if c.midiRpn == 1.0 {
                try self.channelSetTuning(channel, (jsOr(c.tuning, 0)) + (c.midiData - 8192.0) / 8192.0)
            } else if c.midiRpn == 2.0 {
                try self.channelSetTuning(channel, controlValue - 64.0 + (c.tuning - (jsOr(c.tuning, 0))))
            }
            return
        case ControllerType.VolumeCoarse:
            c.midiVolume = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiVolume, 127), jsShl(controlValue, 7)))
            self.channelSetVolume(channel, Math.pow((c.midiVolume / 16383.0) * (c.midiExpression / 16383.0), 3.0))
            return
        case ControllerType.VolumeFine:
            c.midiVolume = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiVolume, 16256), controlValue))
            self.channelSetVolume(channel, Math.pow((c.midiVolume / 16383.0) * (c.midiExpression / 16383.0), 3.0))
            return
        case ControllerType.ExpressionControllerCoarse:
            c.midiExpression = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiExpression, 127), jsShl(controlValue, 7)))
            self.channelSetVolume(channel, Math.pow((c.midiVolume / 16383.0) * (c.midiExpression / 16383.0), 3.0))
            return
        case ControllerType.ExpressionControllerFine:
            c.midiExpression = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiExpression, 16256), controlValue))
            self.channelSetVolume(channel, Math.pow((c.midiVolume / 16383.0) * (c.midiExpression / 16383.0), 3.0))
            return
        case ControllerType.PanCoarse:
            c.midiPan = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiPan, 127), jsShl(controlValue, 7)))
            try self.channelSetPan(channel, c.midiPan / 16383.0)
            return
        case ControllerType.PanFine:
            c.midiPan = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiPan, 16256), controlValue))
            try self.channelSetPan(channel, c.midiPan / 16383.0)
            return
        case ControllerType.DataEntryCoarse:
            c.midiData = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiData, 127), jsShl(controlValue, 7)))
            if c.midiRpn == 0.0 {
                try self.channelSetPitchRange(channel, (jsShr(c.midiData, 7)) + 0.01 * (jsAnd(c.midiData, 127)))
            } else if c.midiRpn == 1.0 {
                try self.channelSetTuning(channel, (jsOr(c.tuning, 0)) + (c.midiData - 8192.0) / 8192.0)
            } else if c.midiRpn == 2.0 && (controller as! ControllerType) == ControllerType.DataEntryCoarse {
                try self.channelSetTuning(channel, controlValue - 64.0 + (c.tuning - (jsOr(c.tuning, 0))))
            }
            return
        case ControllerType.BankSelectCoarse:
            c.bank = TypeConversions.int32ToUint16(jsOr(32768, controlValue))
            return
        case ControllerType.BankSelectFine:
            c.bank = TypeConversions.int32ToUint16(jsOr((jsAnd(c.bank, 32768)) != 0 ? jsShl(jsAnd(c.bank, 127), 7) : 0.0, controlValue))
            return
        case ControllerType.RegisteredParameterCourse:
            c.midiRpn = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiRpn == 65535.0 ? 0.0 : c.midiRpn, 127), jsShl(controlValue, 7)))
            return
        case ControllerType.RegisteredParameterFine:
            c.midiRpn = TypeConversions.int32ToUint16(jsOr(jsAnd(c.midiRpn == 65535.0 ? 0.0 : c.midiRpn, 16256), controlValue))
            return
        case ControllerType.NonRegisteredParameterFine:
            c.midiRpn = 65535.0
            return
        case ControllerType.NonRegisteredParameterCourse:
            c.midiRpn = 65535.0
            return
        case ControllerType.AllSoundOff:
            try self.channelSoundsOffAll(channel)
            return
        case ControllerType.AllNotesOff:
            self.channelNoteOffAll(channel)
            return
        case ControllerType.ResetControllers:
            c.midiVolume = 16383.0
            c.midiExpression = 16383.0
            c.midiPan = 8192.0
            c.bank = 0.0
            self.channelSetVolume(channel, 1.0)
            try self.channelSetPan(channel, 0.5)
            try self.channelSetPitchRange(channel, 2.0)
            return
        default:
            break
        }
    }

    /**
     * Gets the current preset index of the given channel.
     */
    public func channelGetPresetIndex(_ channel: Double) -> Double {
        return TypeHelper.isTruthy(TypeHelper.isTruthy(self._channels) && channel < self._channels!.channelList.length) ? self._channels!.channelList[(channel).toInt()].presetIndex : 0.0
    }

    /**
     * Gets the current bank of the given channel.
     */
    public func channelGetPresetBank(_ channel: Double) -> Double {
        return TypeHelper.isTruthy(TypeHelper.isTruthy(self._channels) && channel < self._channels!.channelList.length) ? jsAnd(self._channels!.channelList[(channel).toInt()].bank, 32767) : 0.0
    }

    /**
     * Gets the current pan of the given channel.
     */
    public func channelGetPan(_ channel: Double) -> Double {
        return TypeHelper.isTruthy(TypeHelper.isTruthy(self._channels) && channel < self._channels!.channelList.length) ? self._channels!.channelList[(channel).toInt()].panOffset - 0.5 : 0.5
    }

    /**
     * Gets the current volume of the given channel.
     */
    public func channelGetVolume(_ channel: Double) -> Double {
        return TypeHelper.isTruthy(TypeHelper.isTruthy(self._channels) && channel < self._channels!.channelList.length) ? SynthHelper.decibelsToGain(self._channels!.channelList[(channel).toInt()].gainDb) : 1.0
    }

    /**
     * Gets the current pitch wheel of the given channel.
     */
    public func channelGetPitchWheel(_ channel: Double) -> Double {
        return TypeHelper.isTruthy(TypeHelper.isTruthy(self._channels) && channel < self._channels!.channelList.length) ? self._channels!.channelList[(channel).toInt()].pitchWheel : 8192.0
    }

    /**
     * Gets the current pitch range of the given channel.
     */
    public func channelGetPitchRange(_ channel: Double) -> Double {
        return TypeHelper.isTruthy(TypeHelper.isTruthy(self._channels) && channel < self._channels!.channelList.length) ? self._channels!.channelList[(channel).toInt()].pitchRange : 2.0
    }

    /**
     * Gets the current tuning of the given channel.
     */
    public func channelGetTuning(_ channel: Double) -> Double {
        return TypeHelper.isTruthy(TypeHelper.isTruthy(self._channels) && channel < self._channels!.channelList.length) ? self._channels!.channelList[(channel).toInt()].tuning : 0.0
    }

    /**
     * Resets all loaded presets.
     */
    public func resetPresets() {
        self.presets = List<Preset>()
    }

    /**
     * Loads the presets from the given SoundFont hydra structure.
     */
    public func loadPresets(_ hydra: Hydra, _ instrumentPrograms: Set<Double>, _ percussionKeys: Set<Double>, _ append: Bool) throws {
        let newPresets: List<Preset> = List<Preset>()
        do {
            var phdrIndex: Double = 0.0
            while phdrIndex < hydra.phdrs.length - 1.0 {
                let phdr: HydraPhdr = hydra.phdrs[(phdrIndex).toInt()]
                var regionIndex: Double = 0.0
                let preset: Preset = Preset()
                newPresets.push(preset)
                preset.name = phdr.presetName
                preset.bank = phdr.bank
                preset.presetNumber = phdr.preset
                var regionNum: Double = 0.0
                do {
                    var pbagIndex: Double = phdr.presetBagNdx
                    while try pbagIndex < hydra.phdrs.jsElement((phdrIndex + 1.0).toInt()).presetBagNdx {
                        let pbag: HydraPbag = hydra.pbags[(pbagIndex).toInt()]
                        var plokey: Double = 0.0
                        var phikey: Double = 127.0
                        var plovel: Double = 0.0
                        var phivel: Double = 127.0
                        do {
                            var pgenIndex: Double = pbag.genNdx
                            while try pgenIndex < hydra.pbags.jsElement((pbagIndex + 1.0).toInt()).genNdx {
                                let pgen: HydraPgen = hydra.pgens[(pgenIndex).toInt()]
                                if pgen.genOper == HydraPgen.GenKeyRange {
                                    plokey = pgen.genAmount.lowByteAmount
                                    phikey = pgen.genAmount.highByteAmount
                                    pgenIndex += 1
                                    continue
                                }
                                if pgen.genOper == HydraPgen.GenVelRange {
                                    plovel = pgen.genAmount.lowByteAmount
                                    phivel = pgen.genAmount.highByteAmount
                                    pgenIndex += 1
                                    continue
                                }
                                if pgen.genOper != HydraPgen.GenInstrument {
                                    pgenIndex += 1
                                    continue
                                }
                                if pgen.genAmount.wordAmount >= hydra.insts.length {
                                    pgenIndex += 1
                                    continue
                                }
                                let pinst: HydraInst = hydra.insts[(pgen.genAmount.wordAmount).toInt()]
                                do {
                                    var ibagIndex: Double = pinst.instBagNdx
                                    while try ibagIndex < hydra.insts.jsElement((pgen.genAmount.wordAmount + 1.0).toInt()).instBagNdx {
                                        let ibag: HydraIbag = hydra.ibags[(ibagIndex).toInt()]
                                        var ilokey: Double = 0.0
                                        var ihikey: Double = 127.0
                                        var ilovel: Double = 0.0
                                        var ihivel: Double = 127.0
                                        do {
                                            var igenIndex: Double = ibag.instGenNdx
                                            while try igenIndex < hydra.ibags.jsElement((ibagIndex + 1.0).toInt()).instGenNdx {
                                                let igen: HydraIgen = hydra.igens[(igenIndex).toInt()]
                                                if igen.genOper == HydraPgen.GenKeyRange {
                                                    ilokey = igen.genAmount.lowByteAmount
                                                    ihikey = igen.genAmount.highByteAmount
                                                    igenIndex += 1
                                                    continue
                                                }
                                                if igen.genOper == HydraPgen.GenVelRange {
                                                    ilovel = igen.genAmount.lowByteAmount
                                                    ihivel = igen.genAmount.highByteAmount
                                                    igenIndex += 1
                                                    continue
                                                }
                                                if igen.genOper == 53.0 && ihikey >= plokey && ilokey <= phikey && ihivel >= plovel && ilovel <= phivel {
                                                    regionNum += 1
                                                }
                                                igenIndex += 1
                                            }
                                        }
                                        ibagIndex += 1
                                    }
                                }
                                pgenIndex += 1
                            }
                        }
                        pbagIndex += 1
                    }
                }
                preset.regions = List<Region>((regionNum).toInt())
                var globalRegion: Region = Region()
                globalRegion.clear(true)
                do {
                    var pbagIndex: Double = phdr.presetBagNdx
                    while try pbagIndex < hydra.phdrs.jsElement((phdrIndex + 1.0).toInt()).presetBagNdx {
                        let pbag: HydraPbag = hydra.pbags[(pbagIndex).toInt()]
                        let presetRegion: Region = Region(globalRegion)
                        var hadGenInstrument: Bool = false
                        do {
                            var pgenIndex: Double = pbag.genNdx
                            while try pgenIndex < hydra.pbags.jsElement((pbagIndex + 1.0).toInt()).genNdx {
                                let pgen: HydraPgen = hydra.pgens[(pgenIndex).toInt()]
                                if pgen.genOper == HydraPgen.GenInstrument {
                                    let whichInst: Double = pgen.genAmount.wordAmount
                                    if whichInst >= hydra.insts.length {
                                        pgenIndex += 1
                                        continue
                                    }
                                    var instRegion: Region = Region()
                                    instRegion.clear(false)
                                    let inst: HydraInst = hydra.insts[(whichInst).toInt()]
                                    do {
                                        var ibagIndex: Double = inst.instBagNdx
                                        while try ibagIndex < hydra.insts.jsElement((whichInst + 1.0).toInt()).instBagNdx {
                                            let ibag: HydraIbag = hydra.ibags[(ibagIndex).toInt()]
                                            let zoneRegion: Region = Region(instRegion)
                                            var hadSampleId: Bool = false
                                            do {
                                                var igenIndex: Double = ibag.instGenNdx
                                                while try igenIndex < hydra.ibags.jsElement((ibagIndex + 1.0).toInt()).instGenNdx {
                                                    let igen: HydraIgen = hydra.igens[(igenIndex).toInt()]
                                                    if igen.genOper == HydraPgen.GenSampleId {
                                                        if zoneRegion.hiKey < presetRegion.loKey || zoneRegion.loKey > presetRegion.hiKey {
                                                            igenIndex += 1
                                                            continue
                                                        }
                                                        if zoneRegion.hiVel < presetRegion.loVel || zoneRegion.loVel > presetRegion.hiVel {
                                                            igenIndex += 1
                                                            continue
                                                        }
                                                        if presetRegion.loKey > zoneRegion.loKey {
                                                            zoneRegion.loKey = presetRegion.loKey
                                                        }
                                                        if presetRegion.hiKey < zoneRegion.hiKey {
                                                            zoneRegion.hiKey = presetRegion.hiKey
                                                        }
                                                        if presetRegion.loVel > zoneRegion.loVel {
                                                            zoneRegion.loVel = presetRegion.loVel
                                                        }
                                                        if presetRegion.hiVel < zoneRegion.hiVel {
                                                            zoneRegion.hiVel = presetRegion.hiVel
                                                        }
                                                        zoneRegion.offset += presetRegion.offset
                                                        zoneRegion.end += presetRegion.end
                                                        zoneRegion.loopStart += presetRegion.loopStart
                                                        zoneRegion.loopEnd += presetRegion.loopEnd
                                                        zoneRegion.transpose += presetRegion.transpose
                                                        zoneRegion.tune += presetRegion.tune
                                                        zoneRegion.pitchKeyTrack += presetRegion.pitchKeyTrack
                                                        zoneRegion.attenuation += presetRegion.attenuation
                                                        zoneRegion.pan += presetRegion.pan
                                                        zoneRegion.ampEnv.delay += presetRegion.ampEnv.delay
                                                        zoneRegion.ampEnv.attack += presetRegion.ampEnv.attack
                                                        zoneRegion.ampEnv.hold += presetRegion.ampEnv.hold
                                                        zoneRegion.ampEnv.decay += presetRegion.ampEnv.decay
                                                        zoneRegion.ampEnv.sustain += presetRegion.ampEnv.sustain
                                                        zoneRegion.ampEnv.release += presetRegion.ampEnv.release
                                                        zoneRegion.modEnv.delay += presetRegion.modEnv.delay
                                                        zoneRegion.modEnv.attack += presetRegion.modEnv.attack
                                                        zoneRegion.modEnv.hold += presetRegion.modEnv.hold
                                                        zoneRegion.modEnv.decay += presetRegion.modEnv.decay
                                                        zoneRegion.modEnv.sustain += presetRegion.modEnv.sustain
                                                        zoneRegion.modEnv.release += presetRegion.modEnv.release
                                                        zoneRegion.initialFilterQ += presetRegion.initialFilterQ
                                                        zoneRegion.initialFilterFc += presetRegion.initialFilterFc
                                                        zoneRegion.modEnvToPitch += presetRegion.modEnvToPitch
                                                        zoneRegion.modEnvToFilterFc += presetRegion.modEnvToFilterFc
                                                        zoneRegion.delayModLFO += presetRegion.delayModLFO
                                                        zoneRegion.freqModLFO += presetRegion.freqModLFO
                                                        zoneRegion.modLfoToPitch += presetRegion.modLfoToPitch
                                                        zoneRegion.modLfoToFilterFc += presetRegion.modLfoToFilterFc
                                                        zoneRegion.modLfoToVolume += presetRegion.modLfoToVolume
                                                        zoneRegion.delayVibLFO += presetRegion.delayVibLFO
                                                        zoneRegion.freqVibLFO += presetRegion.freqVibLFO
                                                        zoneRegion.vibLfoToPitch += presetRegion.vibLfoToPitch
                                                        zoneRegion.ampEnv.envToSecs(true)
                                                        zoneRegion.modEnv.envToSecs(false)
                                                        zoneRegion.delayModLFO = zoneRegion.delayModLFO < -11950.0 ? 0.0 : SynthHelper.timecents2Secs(zoneRegion.delayModLFO)
                                                        zoneRegion.delayVibLFO = zoneRegion.delayVibLFO < -11950.0 ? 0.0 : SynthHelper.timecents2Secs(zoneRegion.delayVibLFO)
                                                        if zoneRegion.pan < -0.5 {
                                                            zoneRegion.pan = -0.5
                                                        } else if zoneRegion.pan > 0.5 {
                                                            zoneRegion.pan = 0.5
                                                        }
                                                        if zoneRegion.initialFilterQ < 1500 || zoneRegion.initialFilterQ > 13500 {
                                                            zoneRegion.initialFilterQ = 0.0
                                                        }
                                                        let shdr: HydraShdr = hydra.sHdrs[(igen.genAmount.wordAmount).toInt()]
                                                        zoneRegion.offset += shdr.start
                                                        zoneRegion.end += shdr.end
                                                        zoneRegion.loopStart += shdr.startLoop
                                                        zoneRegion.loopEnd += shdr.endLoop
                                                        if shdr.endLoop > 0 {
                                                            zoneRegion.loopEnd -= 1.0
                                                        }
                                                        if zoneRegion.pitchKeyCenter == -1.0 {
                                                            zoneRegion.pitchKeyCenter = shdr.originalPitch
                                                        }
                                                        zoneRegion.tune += shdr.pitchCorrection
                                                        zoneRegion.sampleRate = shdr.sampleRate
                                                        let isPercussion: Bool = phdr.bank == SynthConstants.PercussionBank
                                                        let shouldLoadSamples: Bool = (isPercussion && TinySoundFont._setContainsRange(percussionKeys, zoneRegion.loKey, zoneRegion.hiKey)) || (!isPercussion && instrumentPrograms.has(phdr.preset))
                                                        if !shouldLoadSamples {
                                                            Logger.debug("AlphaSynth", "Skipping load of unused sample \((shdr.sampleName).toTemplate()) for preset \((phdr.presetName).toTemplate()) (bank \((preset.bank).toTemplate()) program \((preset.presetNumber).toTemplate()))")
                                                            zoneRegion.samples = Float32Array(0.0)
                                                        } else if (jsAnd(shdr.sampleType, 1)) != 0 {
                                                            Logger.debug("AlphaSynth", "Loading of used sample \((shdr.sampleName).toTemplate()) for preset \((phdr.presetName).toTemplate()) (bank \((preset.bank).toTemplate()) program \((preset.presetNumber).toTemplate()))")
                                                            let decompressVorbis: Bool = (jsAnd(shdr.sampleType, 16)) != 0
                                                            if decompressVorbis {
                                                                try zoneRegion.samples = hydra.decodeSamples(shdr.start, shdr.end, true)
                                                            } else {
                                                                try zoneRegion.samples = hydra.decodeSamples(zoneRegion.offset * 2.0, zoneRegion.end * 2.0, false)
                                                                if zoneRegion.loopStart > 0 {
                                                                    zoneRegion.loopStart -= zoneRegion.offset
                                                                }
                                                                if zoneRegion.loopEnd > 0 {
                                                                    zoneRegion.loopEnd -= zoneRegion.offset
                                                                }
                                                            }
                                                            zoneRegion.offset = 0.0
                                                            zoneRegion.end = zoneRegion.samples.length - 1.0
                                                        } else {
                                                            Logger.warning("AlphaSynth", "Skipping load of unsupported sample \((shdr.sampleName).toTemplate()) for preset \((phdr.presetName).toTemplate()), sample type \((shdr.sampleType).toTemplate()) is not supported (bank \((preset.bank).toTemplate()) program \((preset.presetNumber).toTemplate()))")
                                                            zoneRegion.samples = Float32Array(0.0)
                                                        }
                                                        preset.regions![(regionIndex).toInt()] = Region(zoneRegion)
                                                        regionIndex += 1
                                                        hadSampleId = true
                                                    } else {
                                                        zoneRegion.`operator`(igen.genOper, igen.genAmount)
                                                    }
                                                    igenIndex += 1
                                                }
                                            }
                                            if ibag === hydra.ibags[(inst.instBagNdx).toInt()] && !hadSampleId {
                                                instRegion = Region(zoneRegion)
                                            }
                                            ibagIndex += 1
                                        }
                                    }
                                    hadGenInstrument = true
                                } else {
                                    presetRegion.`operator`(pgen.genOper, pgen.genAmount)
                                }
                                pgenIndex += 1
                            }
                        }
                        if pbag === hydra.pbags[(phdr.presetBagNdx).toInt()] && !hadGenInstrument {
                            globalRegion = presetRegion
                        }
                        pbagIndex += 1
                    }
                }
                phdrIndex += 1
            }
        }
        if !append || !TypeHelper.isTruthy(self.presets) {
            self.presets = newPresets
        } else {
            for preset in newPresets {
                self.presets!.push(preset)
            }
        }
    }

    private static func _setContainsRange(_ x: Set<Double>, _ lo: Double, _ hi: Double) -> Bool {
        do {
            var i: Double = lo
            while i <= hi {
                if x.has(i) {
                    return true
                }
                i += 1
            }
        }
        return false
    }

    /**
     * Checks whether the synth has loaded the samples for a given midi program.
     */
    public func hasSamplesForProgram(_ program: Double) throws -> Bool {
        let presets: List<Preset>? = self.presets
        if !TypeHelper.isTruthy(presets) {
            return false
        }
        for preset in presets! {
            if preset.presetNumber == program {
                for region in try jsNonNull(preset.regions) {
                    if region.samples.length > 0 {
                        return true
                    }
                }
            }
        }
        return false
    }

    /**
     * Checks whether the synth has loaded the samples for a given percussion key.
     */
    public func hasSamplesForPercussion(_ key: Double) throws -> Bool {
        let presets: List<Preset>? = self.presets
        if !TypeHelper.isTruthy(presets) {
            return false
        }
        for preset in presets! {
            if preset.bank == SynthConstants.PercussionBank {
                for region in try jsNonNull(preset.regions) {
                    if region.loKey >= key && region.hiKey <= key && region.samples.length > 0 {
                        return true
                    }
                }
            }
        }
        return false
    }
}
